      { country: "Kenya", income_group: "Lower-Middle", gdp_per_capita_usd: 2100, hdi: 0.575, freedom_index: 48, corruption_perceptions_index: 31, co2_emissions_per_capita_tons: 0.4, military_expenditure_pct_gdp: 1.2, internet_penetration_pct: 40 },
      { country: "Ethiopia", income_group: "Low", gdp_per_capita_usd: 1020, hdi: 0.498, freedom_index: 22, corruption_perceptions_index: 37, co2_emissions_per_capita_tons: 0.2, military_expenditure_pct_gdp: 0.7, internet_penetration_pct: 17 },
      { country: "Mozambique", income_group: "Low", gdp_per_capita_usd: 480, hdi: 0.461, freedom_index: 43, corruption_perceptions_index: 26, co2_emissions_per_capita_tons: 0.2, military_expenditure_pct_gdp: 1.0, internet_penetration_pct: 21 },
      { country: "Uganda", income_group: "Low", gdp_per_capita_usd: 960, hdi: 0.525, freedom_index: 34, corruption_perceptions_index: 26, co2_emissions_per_capita_tons: 0.1, military_expenditure_pct_gdp: 2.2, internet_penetration_pct: 26 },
      { country: "Mali", income_group: "Low", gdp_per_capita_usd: 830, hdi: 0.428, freedom_index: 22, corruption_perceptions_index: 28, co2_emissions_per_capita_tons: 0.1, military_expenditure_pct_gdp: 3.5, internet_penetration_pct: 34 },
      { country: "Chad", income_group: "Low", gdp_per_capita_usd: 690, hdi: 0.394, freedom_index: 15, corruption_perceptions_index: 20, co2_emissions_per_capita_tons: 0.1, military_expenditure_pct_gdp: 2.9, internet_penetration_pct: 14 },
      { country: "Afghanistan", income_group: "Low", gdp_per_capita_usd: 380, hdi: 0.462, freedom_index: 8, corruption_perceptions_index: 24, co2_emissions_per_capita_tons: 0.3, military_expenditure_pct_gdp: 3.3, internet_penetration_pct: 18 }
    ];

    // === CONFIG ===
    var INCOME_GROUPS = ["High", "Upper-Middle", "Lower-Middle", "Low"];
    var GROUP_COLORS = {
      "High": "#3b82f6",
      "Upper-Middle": "#10b981",
      "Lower-Middle": "#f59e0b",
      "Low": "#f43f5e"
    };
    var GROUP_COUNTS = {};
    data.forEach(function(d) {
      GROUP_COUNTS[d.income_group] = (GROUP_COUNTS[d.income_group] || 0) + 1;
    });

    var DIMENSIONS = [
      { key: "gdp_per_capita_usd", label: "GDP per Capita", unit: "USD", format: function(v) { return "$" + d3.format(",.0f")(v); } },
      { key: "hdi", label: "HDI", unit: "0–1", format: function(v) { return v.toFixed(3); } },
      { key: "freedom_index", label: "Freedom Index", unit: "0–100", format: function(v) { return v; } },
      { key: "corruption_perceptions_index", label: "CPI", unit: "0–100", format: function(v) { return v; } },
      { key: "co2_emissions_per_capita_tons", label: "CO₂ per Capita", unit: "tons", format: function(v) { return v + "t"; } },
      { key: "military_expenditure_pct_gdp", label: "Military % GDP", unit: "%", format: function(v) { return v + "%"; } },
      { key: "internet_penetration_pct", label: "Internet", unit: "%", format: function(v) { return v + "%"; } }
    ];

    // === STATE ===
    var activeGroups = { "High": true, "Upper-Middle": true, "Lower-Middle": true, "Low": true };
    var chartBuilt = false;

    // === LEGEND ===
    var legendContainer = document.getElementById("legend-items");
    INCOME_GROUPS.forEach(function(group) {
      var item = document.createElement("div");
      item.className = "legend-item";
      item.id = "legend-" + group.replace(/\s/g,"-");
      item.setAttribute("role", "button");
      item.setAttribute("tabindex", "0");
      item.setAttribute("aria-pressed", "true");
      item.setAttribute("aria-label", "Toggle " + group + " income group");
      item.innerHTML = '<div class="legend-dot" style="background:' + GROUP_COLORS[group] + '"></div>' +
        '<span>' + group + '</span>' +
        '<span class="legend-count">(' + GROUP_COUNTS[group] + ')</span>';
      item.addEventListener("click", function() {
        activeGroups[group] = !activeGroups[group];
        item.classList.toggle("dimmed", !activeGroups[group]);
        item.setAttribute("aria-pressed", activeGroups[group] ? "true" : "false");
        updateVisibility();
      });
      item.addEventListener("keydown", function(e) {
        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); item.click(); }
      });
      legendContainer.appendChild(item);
    });

    // === CHART ===
    var svgEl, yScales = {}, xScale;

    function buildChart() {
      if (typeof d3 === 'undefined') { console.error('D3 not loaded'); return; }

      var container = document.getElementById("parallel-chart");
      container.innerHTML = "";

      var isDark = document.documentElement.classList.contains("theme-dark");
      var textColor = isDark ? "#EDEDED" : "#0f172a";
      var textSecondary = isDark ? "#888" : "#64748b";
      var axisColor = isDark ? "rgba(255,255,255,0.15)" : "rgba(0,0,0,0.2)";
      var gridColor = isDark ? "rgba(255,255,255,0.05)" : "rgba(0,0,0,0.05)";

      var margin = { top: 60, right: 60, bottom: 50, left: 60 };
      var totalW = container.offsetWidth || 1200;
      var totalH = 520;
      var W = totalW - margin.left - margin.right;
      var H = totalH - margin.top - margin.bottom;

      container.style.height = totalH + "px";

      var svg = d3.select("#parallel-chart")
        .append("svg")
        .attr("width", totalW)
        .attr("height", totalH)
        .attr("role", "img")
        .attr("aria-label", "Parallel coordinates showing 7 development dimensions for 30 countries")
        .style("overflow", "visible");

      svgEl = svg;

      var g = svg.append("g")
        .attr("transform", "translate(" + margin.left + "," + margin.top + ")");

      // Scales
      xScale = d3.scalePoint()
        .domain(DIMENSIONS.map(function(d) { return d.key; }))
        .range([0, W])
        .padding(0.1);

      DIMENSIONS.forEach(function(dim) {
        var vals = data.map(function(d) { return +d[dim.key]; });
        var mn = d3.min(vals), mx = d3.max(vals);
        var pad = (mx - mn) * 0.05;
        yScales[dim.key] = d3.scaleLinear()
          .domain([mn - pad, mx + pad])
          .range([H, 0])
          .nice();
      });

      // Line generator
      function path(d) {
        return d3.line()(DIMENSIONS.map(function(dim) {
          return [xScale(dim.key), yScales[dim.key](+d[dim.key])];
        }));
      }

      // Draw lines
      var lines = g.append("g").attr("class", "lines");
      lines.selectAll("path")
        .data(data)
        .enter()
        .append("path")
        .attr("class", "poly-line")
        .attr("data-group", function(d) { return d.income_group; })
        .attr("data-country", function(d) { return d.country; })
        .attr("d", path)
        .attr("stroke", function(d) { return GROUP_COLORS[d.income_group]; })
        .attr("tabindex", "0")
        .attr("aria-label", function(d) { return d.country + ", " + d.income_group + " income"; })
        .on("mouseenter", function(event, d) {
          d3.selectAll(".poly-line").classed("dimmed", true);
          d3.select(this).classed("dimmed", false).classed("highlighted", true);
          showTooltip(event, d);
        })
        .on("mousemove", function(event, d) {
          moveTooltip(event);
        })
        .on("mouseleave", function(event, d) {
          d3.selectAll(".poly-line").classed("dimmed", false).classed("highlighted", false);
          hideTooltip();
        })
        .on("focus", function(event, d) {
          d3.selectAll(".poly-line").classed("dimmed", true);
          d3.select(this).classed("dimmed", false).classed("highlighted", true);
        })
        .on("blur", function() {
          d3.selectAll(".poly-line").classed("dimmed", false).classed("highlighted", false);
        });

      // Draw axes
      var axisG = g.append("g").attr("class", "axes");

      DIMENSIONS.forEach(function(dim) {
        var x = xScale(dim.key);
        var axG = axisG.append("g")
          .attr("transform", "translate(" + x + ",0)");

        // Axis line
        axG.append("line")
          .attr("y1", 0)
          .attr("y2", H)
          .attr("stroke", axisColor)
          .attr("stroke-width", 1.5);

        // Tick marks
        var tickCount = 5;
        var ticks = yScales[dim.key].ticks(tickCount);
        ticks.forEach(function(tick) {
          var y = yScales[dim.key](tick);
          axG.append("line")
            .attr("x1", -4).attr("x2", 4)
            .attr("y1", y).attr("y2", y)
            .attr("stroke", axisColor)
            .attr("stroke-width", 1);
          axG.append("text")
            .attr("x", -8)
            .attr("y", y)
            .attr("text-anchor", "end")
            .attr("dy", "0.35em")
            .attr("fill", textSecondary)
            .attr("font-size", "9")
            .attr("font-family", "Inter, sans-serif")
            .text(dim.format(tick));
        });

        // Axis label (top)
        var labelLines = dim.label.split(" ");
        var labelY = -12;
        if (labelLines.length > 1) {
          labelY = -20;
          axG.append("text")
            .attr("y", labelY)
            .attr("text-anchor", "middle")
            .attr("fill", textColor)
            .attr("font-size", "11")
            .attr("font-weight", "600")
            .attr("font-family", "Inter, sans-serif")
            .attr("letter-spacing", "0.02em")
            .text(labelLines[0]);
          axG.append("text")
            .attr("y", labelY + 13)
            .attr("text-anchor", "middle")
            .attr("fill", textColor)
            .attr("font-size", "11")
            .attr("font-weight", "600")
            .attr("font-family", "Inter, sans-serif")
            .text(labelLines.slice(1).join(" "));
          // Unit
          axG.append("text")
            .attr("y", labelY + 26)
            .attr("text-anchor", "middle")
            .attr("fill", textSecondary)
            .attr("font-size", "9")
            .attr("font-family", "Inter, sans-serif")
            .text("(" + dim.unit + ")");
        } else {
          axG.append("text")
            .attr("y", labelY)
            .attr("text-anchor", "middle")
            .attr("fill", textColor)
            .attr("font-size", "11")
            .attr("font-weight", "600")
            .attr("font-family", "Inter, sans-serif")
            .text(dim.label);
          axG.append("text")
            .attr("y", labelY - 12)
            .attr("text-anchor", "middle")
            .attr("fill", textSecondary)
            .attr("font-size", "9")
            .attr("font-family", "Inter, sans-serif")
            .text("(" + dim.unit + ")");
        }

        // Subtle background band
        axG.append("rect")
          .attr("x", -xScale.step() / 2 + 1)
          .attr("y", 0)
          .attr("width", xScale.step() - 2)
          .attr("height", H)
          .attr("fill", gridColor)
          .attr("rx", 2)
          .lower();
      });

      chartBuilt = true;
      updateVisibility();
    }

    function updateVisibility() {
      d3.selectAll(".poly-line").each(function() {
        var el = d3.select(this);
        var group = el.attr("data-group");
        if (!activeGroups[group]) {
          el.style("opacity", 0).style("pointer-events", "none");
        } else {
          el.style("opacity", null).style("pointer-events", null);
        }
      });
    }

    // === TOOLTIP ===
    var tooltip = document.getElementById("tooltip");
    function showTooltip(event, d) {
      var color = GROUP_COLORS[d.income_group];
      var rows = DIMENSIONS.map(function(dim) {
        return '<div class="tt-row"><span>' + dim.label + '</span><span>' + dim.format(+d[dim.key]) + '</span></div>';
      }).join("");
      tooltip.innerHTML = '<div class="tt-country">' + d.country + '</div>' +
        '<span class="tt-badge" style="background:' + color + '22;color:' + color + '">' +
        '<span style="width:8px;height:8px;border-radius:50%;background:' + color + ';display:inline-block;"></span>' +
        d.income_group + ' Income</span>' +
        rows;
      tooltip.classList.add("visible");
      moveTooltip(event);
    }
    function moveTooltip(event) {
      var x = event.clientX + 16;
      var y = event.clientY - 10;
      if (x + 240 > window.innerWidth) x = event.clientX - 256;
      if (y + 300 > window.innerHeight) y = event.clientY - 290;
      tooltip.style.left = x + "px";
      tooltip.style.top = y + "px";
    }
    function hideTooltip() {
      tooltip.classList.remove("visible");
    }

    // === MENU ===
    function toggleMenu() {
      var dropdown = document.getElementById("vizMenuDropdown");
      if (dropdown) dropdown.classList.toggle("open");
    }
    document.addEventListener("click", function(e) {
      if (!e.target.closest(".viz-menu")) {
        var dropdown = document.getElementById("vizMenuDropdown");
        if (dropdown) dropdown.classList.remove("open");
      }
    });
    document.addEventListener("keydown", function(e) {
      if (e.key === "Escape") {
        var dropdown = document.getElementById("vizMenuDropdown");
        if (dropdown) dropdown.classList.remove("open");
      }
    });

    // === THEME ===
    var savedTheme = localStorage.getItem("viz-theme");
    var currentTheme = savedTheme || (window.matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark");
    function applyTheme(t) {
      document.documentElement.className = "theme-" + t;
      document.getElementById("themeIcon").textContent = t === "dark" ? "🌙" : "☀️";
      document.getElementById("themeLabel").textContent = t === "dark" ? "Dark" : "Light";
      localStorage.setItem("viz-theme", t);
      currentTheme = t;
      if (typeof onThemeChange === "function") onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === "dark" ? "light" : "dark"); }
    applyTheme(currentTheme);

    function onThemeChange() {
      chartBuilt = false;
      buildChart();
    }

    // === SCROLL REVEAL ===
    document.querySelectorAll("[data-reveal]").forEach(function(el) { el.classList.add("reveal"); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) {
        if (e.isIntersecting) { e.target.classList.add("visible"); revealObserver.unobserve(e.target); }
      });
    }, { threshold: 0.1 });
    document.querySelectorAll(".reveal").forEach(function(el) { revealObserver.observe(el); });

    // === DOWNLOAD PNG ===
    async function downloadImage() {
      var menu = document.querySelector(".viz-menu");
      menu.style.display = "none";
      try {
        var url = await htmlToImage.toPng(document.body, {
          quality: 1,
          pixelRatio: 2,
          filter: function(n) { return !n.classList || !n.classList.contains("viz-menu"); }
        });
        var a = document.createElement("a");
        a.href = url;
        a.download = "national-development-parallel-coordinates.png";
        a.click();
      } catch(e) { console.error("Download failed:", e); }
      menu.style.display = "";
    }

    // === INIT ===
    window.addEventListener("load", function() {
      buildChart();
    });

    // Resize handler
    var resizeTimer;
    window.addEventListener("resize", function() {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(function() {
        chartBuilt = false;
        buildChart();
      }, 200);
    });
  </script>
</body>
